-- "One God, Three Persons" was the only active learning-path topic with no
-- Hindi or Malayalam translation, so its title, description and category
-- label showed in English in the Hindi and Malayalam lesson lists.
-- Terminology follows the existing translations (त्रिएकता / ത്രിത്വം,
-- category "विश्वास की नींव" / "വിശ്വാസത്തിന്റെ അടിത്തറകൾ").

INSERT INTO public.recommended_topics_translations (topic_id, language_code, title, description, category)
VALUES
(
  '111e8400-e29b-41d4-a716-4466554400f1',
  'hi',
  'एक परमेश्वर, तीन व्यक्ति',
  'पवित्र शास्त्र सिखाता है कि परमेश्वर तत्व में एक और व्यक्तियों में तीन है: पिता, पुत्र और पवित्र आत्मा — न तो तीन देवता, और न ही एक परमेश्वर जो तीन मुखौटे पहनता है। यह अध्ययन पुराने और नए नियम में इस सत्य की बाइबलीय नींव को खोजता है — शेमा की इस घोषणा से कि प्रभु एक ही है (व्यवस्थाविवरण 6:4), यीशु के बपतिस्मे तक, जहाँ पिता, पुत्र और आत्मा एक साथ उपस्थित हैं (मत्ती 3:16-17), और मसीह की उस आज्ञा तक कि तीनों के एक ही नाम में बपतिस्मा दिया जाए (मत्ती 28:19)। आप सीखेंगे कि त्रिएकता कोई पहेली नहीं जिसे सुलझाना है, बल्कि वही परमेश्वर है जिसने स्वयं को प्रकट किया है; यह सिद्धांत सुसमाचार की रक्षा कैसे करता है — केवल वह पुत्र जो स्वयं परमेश्वर है उद्धार दे सकता है, और केवल वह आत्मा जो स्वयं परमेश्वर है हमारे भीतर वास कर सकता है; और उस प्रश्न का उत्तर कैसे दें जो नए विश्वासी से सबसे अधिक पूछा जाता है: "तो क्या मसीही तीन देवताओं की आराधना करते हैं?" आपका उत्तर शेमा से बचकर नहीं, बल्कि उसकी पुष्टि करके दिया जाएगा: वही शास्त्र जो घोषणा करता है कि प्रभु एक ही है, पुत्र और आत्मा को भी परमेश्वर कहता है — इसलिए आप एकेश्वरवाद से परे कोई तीसरा विकल्प नहीं दे रहे, बल्कि इस्राएल के साथ यह अंगीकार कर रहे हैं कि प्रभु एक ही है।',
  'विश्वास की नींव'
),
(
  '111e8400-e29b-41d4-a716-4466554400f1',
  'ml',
  'ഏക ദൈവം, മൂന്ന് വ്യക്തികൾ',
  'ദൈവം സത്തയിൽ ഒന്നും വ്യക്തികളിൽ മൂന്നുമാണെന്ന് തിരുവെഴുത്ത് പഠിപ്പിക്കുന്നു: പിതാവ്, പുത്രൻ, പരിശുദ്ധാത്മാവ് — മൂന്ന് ദൈവങ്ങളല്ല, മൂന്ന് മുഖംമൂടികൾ ധരിക്കുന്ന ഒരു ദൈവവുമല്ല. കർത്താവ് ഏകൻ എന്ന ഷെമയുടെ പ്രഖ്യാപനം (ആവർത്തനം 6:4) മുതൽ, പിതാവും പുത്രനും ആത്മാവും ഒരുമിച്ച് സന്നിഹിതരായ യേശുവിന്റെ സ്നാനം (മത്തായി 3:16-17) വഴി, മൂവരുടെയും ഏക നാമത്തിൽ സ്നാനം കഴിപ്പിക്കാനുള്ള ക്രിസ്തുവിന്റെ കല്പന (മത്തായി 28:19) വരെ, പഴയതും പുതിയതുമായ നിയമങ്ങളിൽ ഈ സത്യത്തിന്റെ ബൈബിൾ അടിസ്ഥാനം ഈ പഠനം പിന്തുടരുന്നു. ത്രിത്വം പരിഹരിക്കേണ്ട ഒരു കടങ്കഥയല്ല, സ്വയം വെളിപ്പെടുത്തിയ ദൈവം തന്നെയാണെന്നും; ഈ ഉപദേശം സുവിശേഷത്തെ എങ്ങനെ സംരക്ഷിക്കുന്നുവെന്നും — ദൈവമായ പുത്രന് മാത്രമേ രക്ഷിക്കാൻ കഴിയൂ, ദൈവമായ ആത്മാവിന് മാത്രമേ നമ്മിൽ വസിക്കാൻ കഴിയൂ — ഒരു പുതിയ വിശ്വാസിയോട് ഏറ്റവും കൂടുതൽ ചോദിക്കപ്പെടുന്ന "അപ്പോൾ ക്രിസ്ത്യാനികൾ മൂന്ന് ദൈവങ്ങളെ ആരാധിക്കുന്നുണ്ടോ?" എന്ന ചോദ്യത്തിന് എങ്ങനെ മറുപടി പറയണമെന്നും നിങ്ങൾ പഠിക്കും. നിങ്ങളുടെ മറുപടി ഷെമയെ ഒഴിവാക്കുകയല്ല, ഉറപ്പിക്കുകയാണ്: കർത്താവ് ഏകൻ എന്ന് പ്രഖ്യാപിക്കുന്ന അതേ തിരുവെഴുത്ത് പുത്രനെയും ആത്മാവിനെയും ദൈവം എന്ന് വിളിക്കുന്നു — അതിനാൽ നിങ്ങൾ ഏകദൈവവിശ്വാസത്തിനപ്പുറം മൂന്നാമതൊരു വഴി നിർദ്ദേശിക്കുകയല്ല, കർത്താവ് ഏകൻ എന്ന് യിസ്രായേലിനോടൊപ്പം ഏറ്റുപറയുകയാണ്.',
  'വിശ്വാസത്തിന്റെ അടിത്തറകൾ'
)
